import type { WixDataSaveOptions } from './types'

/**
 * Options builder for save operations.
 *
 * Use this builder to configure save behavior such as hooks suppression,
 * and saving reference values.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataSaveOptionsBuilder {
  /**
   * Sets whether to suppress save hooks.
   *
   * When `true`, the save operation runs without triggering hooks.
   */
  withSuppressHooks(value: boolean): WixDataSaveOptionsBuilder
  /**
   * Sets whether to include draft items when saving items.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataSaveOptionsBuilder
  /**
   * Sets whether to include referenced items in the save response.
   * @internal
   */
  withIncludeReferences(value: boolean): WixDataSaveOptionsBuilder
  /**
   * Sets whether to save reference values from the data item.
   */
  withSaveReferences(value: boolean): WixDataSaveOptionsBuilder
  /**
   * Builds the save options object.
   */
  build(): WixDataSaveOptions
}

class WixDataSaveOptionsBuilderImpl implements WixDataSaveOptionsBuilder {
  constructor(private readonly options: WixDataSaveOptions = {}) {}

  withSuppressHooks(value: boolean): WixDataSaveOptionsBuilder {
    return this.copy({ suppressHooks: value })
  }

  withShowDrafts(value: boolean): WixDataSaveOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  withIncludeReferences(value: boolean): WixDataSaveOptionsBuilder {
    return this.copy({ includeReferences: value })
  }

  withSaveReferences(value: boolean): WixDataSaveOptionsBuilder {
    return this.copy({ saveReferences: value })
  }

  build(): WixDataSaveOptions {
    return { ...this.options }
  }

  private copy(options: WixDataSaveOptions): WixDataSaveOptionsBuilder {
    return new WixDataSaveOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new save options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create a save options builder"
 * import { items, SaveOptionsBuilder } from '@wix/data'
 *
 * const options = SaveOptionsBuilder()
 *   .withSuppressHooks(true)
 *   .build()
 *
 * const savedItem = await items.save<MyItem>(
 *   'myCollection',
 *   { _id: 'myItemId', title: 'Updated title' },
 *   options
 * )
 * ```
 */
export const SaveOptionsBuilder: () => WixDataSaveOptionsBuilder = () =>
  new WixDataSaveOptionsBuilderImpl()
